const body = $input.first().json.body ?? $input.first().json;

const tiposSuportados = ['csv', 'json', 'txt', 'md', 'pdf', 'docx', 'odt'];
const ext = (body.ext ?? '').toLowerCase();

if (!body.url_arquivo || !ext) return [];

if (!tiposSuportados.includes(ext)) {
  return [{
    json: {
      erro: true,
      resposta: `**JARVIS:** Formato \`.${ext}\` não suportado. Aceitos: ${tiposSuportados.join(', ')}`,
      channel_id: body.channel_id
    }
  }];
}

return [{
  json: {
    erro: false,
    channel_id: body.channel_id ?? '',
    url_arquivo: body.url_arquivo,
    filename: body.filename ?? 'arquivo',
    ext,
    autor: body.autor ?? 'usuário',
    instrucao: body.instrucao || 'Analise este arquivo e me dê um resumo estruturado.'
  }
}];

const item = $input.first();
const validado = $('js valida arquivo').first().json;
const ext = validado.ext;

const binaryKey = Object.keys(item.binary ?? {})[0];
if (!binaryKey) throw new Error('Arquivo binário não encontrado');

const buffer = Buffer.from(item.binary[binaryKey].data, 'base64');

let texto = '';

if (['txt', 'md'].includes(ext)) {
  texto = buffer.toString('utf-8');

} else if (ext === 'csv') {
  const linhas = buffer.toString('utf-8').split('\n');
  texto = linhas.slice(0, 100).join('\n');
  if (linhas.length > 100) texto += `\n...(${linhas.length - 100} linhas omitidas)`;

} else if (ext === 'json') {
  try {
    const parsed = JSON.parse(buffer.toString('utf-8'));
    texto = JSON.stringify(parsed, null, 2);
  } catch(e) {
    texto = buffer.toString('utf-8');
  }

} else if (ext === 'docx') {
  const mammoth = require('mammoth');
  const result = await mammoth.extractRawText({ buffer });
  texto = result.value;

} else if (ext === 'pdf') {
  const pdfParse = require('pdf-parse');
  const result = await pdfParse(buffer);
  texto = result.text;

} else if (ext === 'odt') {
  const AdmZip = require('adm-zip');
  const zip = new AdmZip(buffer);
  const xml = zip.readAsText('content.xml');
  texto = xml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

} else {
  texto = '(formato não suportado para extração)';
}

if (texto.length > 4000) texto = texto.substring(0, 4000) + '\n...(truncado)';

// Recupera metadados do node de validação para não perder channel_id etc
return [{
  json: {
    channel_id: validado.channel_id,
    filename: validado.filename,
    ext,
    autor: validado.autor,
    instrucao: validado.instrucao,
    texto
  }
}];

