const fs = require('fs');
const lmResponse = $input.first().json;
const ctx = $('js extrai texto').first().json;

const resposta = lmResponse?.choices?.[0]?.message?.content ?? 'Não consegui analisar o arquivo.';
const filename = ctx.filename;
const channel_id = ctx.channel_id;

const arquivosPath = 'D:\\projetos\\Rep\\JARVIS\\JARVIS_BRAIN\\memoria\\arquivos_processados.json';
const dir = 'D:\\projetos\\Rep\\JARVIS\\JARVIS_BRAIN\\memoria';

if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

let historico = [];
try {
  historico = JSON.parse(fs.readFileSync(arquivosPath, 'utf-8'));
  if (!Array.isArray(historico)) historico = [];
} catch(e) { historico = []; }

historico.unshift({
  date: new Date().toISOString().split('T')[0],
  filename,
  analise: resposta,
  run_at: new Date().toISOString()
});

if (historico.length > 30) historico = historico.slice(0, 30);
fs.writeFileSync(arquivosPath, JSON.stringify(historico, null, 2), 'utf-8');

const msg = `**JARVIS — Análise de \`${filename}\`:**\n\n${resposta}`;

return [{ json: { channel_id, resposta: msg } }];
